const meta = {
  NVDA: { company_name: 'NVIDIA', ai_subsector: 'AI Semiconductors' },
  AMD: { company_name: 'Advanced Micro Devices', ai_subsector: 'AI Semiconductors' },
  AVGO: { company_name: 'Broadcom', ai_subsector: 'AI Semiconductors' },
  MSFT: { company_name: 'Microsoft', ai_subsector: 'AI Cloud Infrastructure' },
  AMZN: { company_name: 'Amazon', ai_subsector: 'AI Cloud Infrastructure' },
  GOOGL: { company_name: 'Alphabet', ai_subsector: 'AI Cloud Infrastructure' },
  PLTR: { company_name: 'Palantir', ai_subsector: 'AI Software / Applications' },
  CRM: { company_name: 'Salesforce', ai_subsector: 'AI Software / Applications' },
  NOW: { company_name: 'ServiceNow', ai_subsector: 'AI Software / Applications' },
  VRT: { company_name: 'Vertiv', ai_subsector: 'AI Power / Data Centre Enablers' },
  ETN: { company_name: 'Eaton', ai_subsector: 'AI Power / Data Centre Enablers' },
  CEG: { company_name: 'Constellation Energy', ai_subsector: 'AI Power / Data Centre Enablers' }
};

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
};

const round2 = v => {
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  return Math.round(v * 100) / 100;
};

const data = $json;
if (data.status === 'error') {
  return [{ json: { rows: [], row_count: 0, error: data.message || 'Twelve Data error' } }];
}

const ticker = String(data.meta?.symbol || $('Loop Over AI Stocks').item.json.ticker || '').toUpperCase();
const m = meta[ticker] || {
  company_name: $('Loop Over AI Stocks').item.json.company_name || ticker,
  ai_subsector: $('Loop Over AI Stocks').item.json.ai_subsector || 'Unclassified AI'
};

let values = Array.isArray(data.values) ? data.values : [];
values = values
  .map(v => ({
    date: v.datetime,
    open: toNum(v.open),
    high: toNum(v.high),
    low: toNum(v.low),
    close: toNum(v.close),
    volume: toNum(v.volume)
  }))
  .filter(v => v.date && v.close !== null)
  .sort((a, b) => a.date.localeCompare(b.date));

if (values.length < 2) {
  return [{ json: { rows: [], row_count: 0, error: `Insufficient time series data for ${ticker}` } }];
}

const rows = [];

for (let i = 0; i < values.length; i++) {
  const cur = values[i];
  const prev = i > 0 ? values[i - 1] : null;

  const latestPrice = cur.close;
  const previousClose = prev ? prev.close : null;

  let dayChange = null;
  let dayChangePct = null;
  if (latestPrice !== null && previousClose !== null && previousClose !== 0) {
    dayChange = latestPrice - previousClose;
    dayChangePct = (dayChange / previousClose) * 100;
  }

  const start = Math.max(0, i - 199);
  const closes = values.slice(start, i + 1).map(v => v.close).filter(v => v !== null);
  const ma200 = closes.length >= 200 ? closes.reduce((a, b) => a + b, 0) / closes.length : null;

  let valuationProxy = null;
  if (latestPrice !== null && ma200 !== null && ma200 !== 0) {
    valuationProxy = ((latestPrice - ma200) / ma200) * 100;
  }

  let momentumScore = null;
  if (dayChangePct !== null) {
    momentumScore = Math.max(0, Math.min(100, 50 + dayChangePct * 5));
  }

  let compositeScore = null;
  if (momentumScore !== null && valuationProxy !== null) {
    compositeScore = (momentumScore * 0.6) - (valuationProxy * 0.4);
  }

  let regime = 'Neutral';
  if (momentumScore !== null) {
    if (momentumScore >= 70) regime = 'Strong Momentum';
    else if (momentumScore <= 30) regime = 'Weak Momentum';
  }

  let quadrant = 'Neutral';
  if (momentumScore !== null && valuationProxy !== null) {
    if (momentumScore >= 60 && valuationProxy >= 20) quadrant = 'Overheated Leader';
    else if (momentumScore >= 60 && valuationProxy < 20) quadrant = 'Emerging Leader';
    else if (momentumScore < 60 && valuationProxy >= 20) quadrant = 'Weak & Expensive';
    else if (momentumScore < 60 && valuationProxy < 20) quadrant = 'Depressed / Value';
  }

  rows.push({
    metric_date: cur.date,
    ticker,
    company_name: m.company_name,
    ai_subsector: m.ai_subsector,
    latest_price: round2(latestPrice),
    previous_close: round2(previousClose),
    day_change: round2(dayChange),
    day_change_pct: round2(dayChangePct),
    volume: cur.volume,
    ma200: round2(ma200),
    valuation_proxy: round2(valuationProxy),
    momentum_score: round2(momentumScore),
    composite_score: round2(compositeScore),
    regime,
    quadrant,
    source: 'twelvedata_historical_backfill'
  });
}

return [{ json: { ticker, rows, row_count: rows.length } }];
